SELECT 'batch_022_e9e5d1d1_wav_07' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0b952309-f12','sm-upload-4f002225-23e','sm-upload-505a75f1-b7c','sm-upload-b6fe712d-3a5','sm-upload-b8855014-029','sm-upload-bafd2d2b-bd0','sm-upload-d8657b96-c3e') AND album_id='al-ba482cba45e7e1408c59fa6fe9e5d1d1') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0b952309-f12','sm-upload-4f002225-23e','sm-upload-505a75f1-b7c','sm-upload-b6fe712d-3a5','sm-upload-b8855014-029','sm-upload-bafd2d2b-bd0','sm-upload-d8657b96-c3e') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-ba482cba45e7e1408c59fa6fe9e5d1d1' AND name='洛天依的构成') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-ba482cba45e7e1408c59fa6fe9e5d1d1') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-ba482cba45e7e1408c59fa6fe9e5d1d1') AS calculated_size;
